// POST /uploads/presign  { filename, contentType }
async function presign(req, res) {
  const { filename, contentType } = req.body;
  const key = 'uploads/' + filename;                 // object key from client filename
  const url = await store.getSignedPutUrl({
    key,
    expiresIn: 86400,                                // URL valid 24h
  });
  res.json({ uploadUrl: url, key });
  // metadata row is written later, when the client calls /uploads/confirm
}
